import json, math, subprocess
from pathlib import Path
p=Path('docs/checkpoints/evidence')
s=json.loads((p/'beta-cache-off-tp1.json').read_text())
def span_pieces(wi,ci,lo,hi):
    g=s['wall_geometry_cm'][wi]
    a,b=g['start_cm'],g['end_cm']
    length=math.dist(a,b)
    axis=[(b[k]-a[k])/length for k in range(2)]
    out=[]
    for i in s['physical'][str(ci)]['candidates']:
        c=s['candidates'][i]
        if c['wall_idx']!=wi: continue
        t=sum((c['origin_world'][k]*30.48-a[k])*axis[k] for k in range(2))
        half=sum(abs(sum(c[d][k]*axis[k] for k in range(2)))*c[size]/2 for d,size in [('x_dir','length_cm'),('y_dir','width_cm')])
        if t+half < lo or t-half>hi: continue
        out.append({'index':i,'t_cm':[round(t-half,6),round(t+half,6)],'code':c['logical_code'],'node':c['node_index'],'reason':c['placement_reason']})
    return sorted(out,key=lambda x:x['t_cm'][0])
def compositions(target):
    out=[]
    for a in range((target+1)//40+1):
      for b in range((target+1)//35+1):
       for c in range((target+1)//20+1):
        for d in range((target+1)//10+1):
         rem=target+1-40*a-35*b-20*c-10*d
         if rem<0 or rem%5: continue
         e=rem//5
         if a+b+c+d+e==0: continue
         out.append({'pieces':dict(zip(['B39','B34','B19','C09','C04'],[a,b,c,d,e])),'compensators':d+e,'specials':b,'half_blocks':c})
    return out
